import React, { Component } from 'react'
import PropTypes from 'prop-types'
import { connect } from 'react-redux'
import { get } from 'lodash'
import { Form, Row, Col, Button, notification } from 'antd'
import EditPageActions from '../../../../../../redux/productConfig/actions'
import ModalWrapper from '../../../../components/Modal'
import EditProductConfigStyleWrapper from './index.style'
import { getFormItems } from '../../../../components/formItem'

const {
  editProduct,
  getProductCategories,
  resetProductConfigRedux
} = EditPageActions
class EditProductConfig extends Component {
  state = {
    category: []
  }
  componentWillReceiveProps (nextProps) {
    const {
      categoryList,
      categoriesMessage,
      editProductMessage,
      editProductData
    } = nextProps
    if (categoriesMessage === 'success') {
      this.setState({
        category: get(categoryList, 'data.details', [])
      })
      this.props.resetProductConfigRedux(['getProductCategoriesMessage'])
    }
    if (editProductMessage === 'success') {
      notification['success'](
        { message: get(editProductData, 'message') }
      )
      this.props.closeModal()
      this.props.resetProductConfigRedux(['editProductMessage'])
    }
    if (editProductMessage !== 'success' && editProductMessage !== undefined) {
      notification['error'](
        { message: 'Failed to Edit Product' }
      )
      this.props.resetProductConfigRedux(['editProductMessage'])
    }
  }
  componentDidMount () {
    this.props.getProductCategories()
  }
  submitHandler =(e) => {
    e.preventDefault()
    this.props.form.validateFieldsAndScroll((err, values) => {
      if (!err) {
        this.props.editProduct({ query: {
          productCode: get(values, 'code')
        },
        body: {
          name: get(values, 'name'),
          category_id: get(values, 'category_id')
        } })
      }
    })
  }
  render () {
    const { category } = this.state
    const {
      categoryListLoading,
      categoriesError,
      visible,
      formInitialValue,
      editProductLoading,
      editProductError
    } = this.props
    return (
      <ModalWrapper
        title='Edit Product Info'
        visible={visible}
        cancelSubmit={this.props.closeModal}
        width='450px'
      >
        <EditProductConfigStyleWrapper>
          <Form onSubmit={this.submitHandler}>
            <Row type='flex' justify='center'>
              <Col span={24}>
                <Row type='flex' justify='space-between'>
                  <Col>
                    <p>Product Code</p>
                  </Col>
                  <Col>
                    {
                      getFormItems.call(this, {
                        formName: 'code',
                        type: 'alphanumeric',
                        required: true,
                        className: 'small-size',
                        disableField: true,
                        initialValue: get(formInitialValue, 'code', '')
                      })
                    }
                  </Col>
                </Row>
              </Col>
              <Col span={24}>
                <Row type='flex' justify='space-between'>
                  <Col>
                    <p>Product Name</p>
                  </Col>
                  <Col>
                    {
                      getFormItems.call(this, {
                        formName: 'name',
                        type: 'alphanumeric',
                        required: true,
                        className: 'small-size',
                        initialValue: get(formInitialValue, 'name', '')
                      })
                    }
                  </Col>
                </Row>
              </Col>
              <Col span={24}>
                <Row type='flex' justify='space-between'>
                  <Col>
                    <p>Category</p>
                  </Col>
                  <Col>
                    {
                      getFormItems.call(this, {
                        formName: 'category_id',
                        type: 'choices',
                        required: true,
                        options: category || [],
                        optionKey: 'id',
                        loading: categoryListLoading && !categoriesError,
                        optionDisplayName: 'name',
                        className: 'small-size',
                        initialValue: get(formInitialValue, 'category_id', '')
                      })
                    }
                  </Col>
                </Row>
              </Col>
            </Row>
            <Row type='flex' justify='center' gutter={80}>
              <Col>
                <Button onClick={this.props.closeModal}>Cancel</Button>
              </Col>
              <Col>
                <Button
                  type='primary'
                  htmlType='submit'
                  loading={editProductLoading && !editProductError}
                >Submit</Button>
              </Col>
            </Row>
          </Form>
        </EditProductConfigStyleWrapper>
      </ModalWrapper>
    )
  }
}
EditProductConfig.defaultProps = {
  categoriesError: false,
  categoryList: {
    data: {
      details: []
    },
    message: '',
    success: true
  },
  categoryListLoading: false,
  formInitialValue: {},
  visible: false,
  editProductLoading: false,
  editProductError: false,
  editProductData: {}
}
EditProductConfig.propTypes = {
  categoriesError: PropTypes.bool,
  categoryList: PropTypes.shape({
    data: PropTypes.shape({
      details: PropTypes.arrayOf(PropTypes.object)
    }),
    message: PropTypes.string,
    success: PropTypes.string
  }),
  categoryListLoading: PropTypes.bool,
  formInitialValue: PropTypes.object,
  visible: PropTypes.bool,
  editProductMessage: PropTypes.string,
  editProductLoading: PropTypes.bool,
  editProductError: PropTypes.bool,
  editProductData: PropTypes.object
}

const WrappedComponent = Form.create()(EditProductConfig)
export default connect(
  state => ({
    categoryList: state.ProductConfigurable.getProductCategories,
    categoryListLoading: state.Loading.GET_PRODUCT_CATEGORIES,
    categoriesError: state.Error.GET_PRODUCT_CATEGORIES,
    categoriesMessage: state.ProductConfigurable.getProductCategoriesMessage,
    editProductLoading: state.Loading.EDIT_PRODUCT_CONFIG,
    editProductError: state.Error.EDIT_PRODUCT_CONFIG,
    editProductMessage: state.ProductConfigurable.editProductMessage,
    editProductData: state.ProductConfigurable.editProductData
  }), {
    editProduct,
    getProductCategories,
    resetProductConfigRedux
  }
)(WrappedComponent)
