import { Modal, Row, Col, Button, Input } from 'antd'
import { TableSectionContainer } from './index.style'

export default function ExistingExportPackageModal ({ loading, visible, onOk, onCancel, existingPackageData, changeModalInputField }) {
  return (
    <Modal
      title='Existing Package Code Already Exists'
      visible={visible}
      onOk={onOk}
      onCancel={onCancel}
      footer={[
        <Button key='cancel' type='default' onClick={onCancel}>Cancel</Button>,
        <Button loading={loading} key='submit' type='primary' onClick={onOk}>Submit</Button>
      ]}
    >
      <Row type='flex' justify='center'>
        <Col span={24}>
          <TableSectionContainer length={existingPackageData.length}>
            <table>
              <thead>
                <tr className='table_tr_border_bottom'>
                  <th className='table__th_border_right'>Existing Package</th>
                  <th className='table__th_width'>Importing Packages</th>
                </tr>
              </thead>
              <tbody>
                {
                  existingPackageData.map((item, index) => {
                    return (
                      <tr key={index} className='table__tr_border_bottom'>
                        <td className='table__td_border_right'>{item.code}</td>
                        <td className='table__td_padding'>
                          <Row type='flex' justify='space-around' align='middle' gutter={20}>
                            <Col span={4} className='tr__td_name'>Name</Col>
                            <Col span={18} className='tr__td_name'><Input value={item.name_value} onChange={(e) => changeModalInputField(e, item.id, 'name')} /></Col>
                            <Col span={4} className='tr__td_code'>Code</Col>
                            <Col span={18} className='tr__td_code'><Input value={item.value} onChange={(e) => changeModalInputField(e, item.id, 'code')} /></Col>
                          </Row>
                        </td>
                      </tr>
                    )
                  })
                }
              </tbody>
            </table>
          </TableSectionContainer>
        </Col>
      </Row>
    </Modal>
  )
}
